lib/alpaca.ts:
/**
 * Alpaca is the single market-data provider. Finnhub, FMP and Twelve Data are
 * gone; every quote, bar, asset lookup, mover and news item on this backend now
 * comes from here.
 *
 * Required environment variables:
 *   ALPACA_API_KEY_ID       — the key id
 *   ALPACA_API_SECRET_KEY   — its secret
 *
 * These calls request the IEX feed. API access does not establish permission
 * to redistribute data in a website or app: confirm the applicable Alpaca and
 * exchange agreements separately (docs/web-investing-readiness.md).
 * IEX is one venue rather than the consolidated tape, so its volume is a
 * share of the market's and its last price can differ slightly from SIP; that
 * is a real feed limitation. SIP access and external display rights both need
 * separate confirmation before changing the feed or releasing distribution.
 */

const KEY_ID = process.env.ALPACA_API_KEY_ID
const SECRET_KEY = process.env.ALPACA_API_SECRET_KEY

export const isAlpacaConfigured = Boolean(KEY_ID && SECRET_KEY)

/** The data feed the free plan serves. */
export const FEED = "iex"

const DATA_BASE = "https://data.alpaca.markets"
/**
 * Assets live on the trading API, not the data API, and the two hosts do not
 * accept the same credentials. Paper-trading keys are refused by the LIVE host,
 * `get` turns the refusal into null, and the caller renders a bare symbol where
 * a company name should be. That is what shipped: .env.example tells the
 * operator "a paper-trading account is enough", which is true of
 * data.alpaca.markets and false of this host, so every company name in the app
 * came back empty and /api/stock-search answered [] for every query while the
 * prices beside them stayed correct.
 *
 * The host therefore has to be nameable per deployment. Set ALPACA_TRADING_BASE
 * to "https://paper-api.alpaca.markets" when the keys belong to a paper
 * account; the live host stays the default, so a live-keyed deployment is
 * unchanged. The value is trimmed and tested for emptiness rather than read
 * with `??`, because a variable added in the Vercel UI and left blank arrives
 * as "": `??` would accept it, every asset URL would become a relative path
 * that fetch rejects, and the result would be the same silent null this change
 * exists to remove.
 */
const TRADING_BASE = process.env.ALPACA_TRADING_BASE?.trim() || "https://api.alpaca.markets"

function headers(): Record<string, string> {
    return {
        "APCA-API-KEY-ID": KEY_ID ?? "",
        "APCA-API-SECRET-KEY": SECRET_KEY ?? "",
        Accept: "application/json",
    }
}

/** Host and status pairs already logged, so a bad key reports once, not once per request. */
const warnedRefusals = new Set<string>()

/**
 * A refusal and an empty answer both reach the caller as null, which is how
 * every company name in the app could go missing for days with nothing in the
 * logs to say the trading host was turning us away. lib/sec.ts draws the same
 * line for EDGAR and says so out loud; this does it for Alpaca, once per host
 * and status so a restart is not needed to hear about a new kind of failure.
 *
 * 404 stays silent on purpose: on /v2/assets it means the symbol does not
 * exist, which is a real answer rather than a door closed in our face.
 */
function warnRefusal(url: string, status: number) {
    if (status !== 401 && status !== 403 && status !== 429) return
    let host = url
    try {
        host = new URL(url).host
    } catch {
        // A malformed url is still worth naming in the log, so keep the raw string.
    }
    const seen = `${host} ${status}`
    if (warnedRefusals.has(seen)) return
    warnedRefusals.add(seen)
    if (status === 429) {
        console.warn(`[alpaca] 429 from ${host}. The plan's calls-per-minute ceiling is being hit.`)
        return
    }
    console.warn(
        `[alpaca] ${status} from ${host}. This is a credential mismatch, not a missing symbol: ` +
            `paper keys are accepted by data.alpaca.markets and paper-api.alpaca.markets and ` +
            `refused by api.alpaca.markets. Set ALPACA_TRADING_BASE if these are paper keys.`
    )
}

/** GET returning parsed JSON, or null on any failure. Callers degrade to "—". */
async function get<T>(url: string, revalidate: number): Promise<T | null> {
    if (!isAlpacaConfigured) return null
    try {
        const res = await fetch(url, { headers: headers(), next: { revalidate } })
        if (!res.ok) {
            warnRefusal(url, res.status)
            return null
        }
        return (await res.json()) as T
    } catch {
        return null
    }
}

/**
 * The app and the site both write crypto pairs the provider-neutral way
 * ("BTCUSD"); Alpaca's crypto endpoints want "BTC/USD".
 */
const CRYPTO_QUOTES = ["USD", "USDT", "USDC", "BTC"]

export function isCryptoSymbol(symbol: string): boolean {
    if (symbol.includes("/")) return true
    return CRYPTO_QUOTES.some(
        (quote) => symbol.endsWith(quote) && symbol.length > quote.length + 1 && !symbol.includes(".")
    )
}

export function toAlpacaCrypto(symbol: string): string {
    if (symbol.includes("/")) return symbol
    const quote = CRYPTO_QUOTES.find((candidate) => symbol.endsWith(candidate))
    if (!quote) return symbol
    return `${symbol.slice(0, -quote.length)}/${quote}`
}

/** "BTC/USD" → "BTCUSD", so responses echo the symbol the caller asked for. */
export function fromAlpacaCrypto(symbol: string): string {
    return symbol.replace("/", "")
}

// MARK: - Snapshots (quotes)

export type AlpacaBar = { t: string; o: number; h: number; l: number; c: number; v: number }

export type AlpacaSnapshot = {
    latestTrade?: { p: number; t: string }
    latestQuote?: { ap: number; bp: number }
    dailyBar?: AlpacaBar
    prevDailyBar?: AlpacaBar
    minuteBar?: AlpacaBar
}

/** Snapshots for a batch of equity symbols, keyed by symbol. */
export async function stockSnapshots(
    symbols: string[],
    revalidate = 60
): Promise<Record<string, AlpacaSnapshot>> {
    if (symbols.length === 0) return {}
    const url = `${DATA_BASE}/v2/stocks/snapshots?symbols=${encodeURIComponent(symbols.join(","))}&feed=${FEED}`
    const json = await get<Record<string, AlpacaSnapshot> & { snapshots?: Record<string, AlpacaSnapshot> }>(
        url,
        revalidate
    )
    if (!json) return {}
    // The endpoint has shipped both shapes; accept either.
    return json.snapshots ?? (json as Record<string, AlpacaSnapshot>)
}

/** Snapshots for crypto pairs, keyed by the caller's own symbol form. */
export async function cryptoSnapshots(
    symbols: string[],
    revalidate = 60
): Promise<Record<string, AlpacaSnapshot>> {
    if (symbols.length === 0) return {}
    const pairs = symbols.map(toAlpacaCrypto)
    const url = `${DATA_BASE}/v1beta3/crypto/us/snapshots?symbols=${encodeURIComponent(pairs.join(","))}`
    const json = await get<{ snapshots?: Record<string, AlpacaSnapshot> }>(url, revalidate)
    const snapshots = json?.snapshots ?? {}
    const out: Record<string, AlpacaSnapshot> = {}
    for (const [pair, snapshot] of Object.entries(snapshots)) {
        out[fromAlpacaCrypto(pair)] = snapshot
    }
    return out
}

/** The last price a snapshot can honestly report, or null. */
export function snapshotPrice(snapshot: AlpacaSnapshot | undefined): number | null {
    const price =
        snapshot?.latestTrade?.p ??
        snapshot?.minuteBar?.c ??
        snapshot?.dailyBar?.c ??
        snapshot?.prevDailyBar?.c
    return typeof price === "number" && price > 0 ? price : null
}

/**
 * The day's move, measured against the previous session's close — the same
 * reference the app's headline percentage uses. null when either side is
 * missing, so nothing is invented.
 */
export function snapshotChange(
    snapshot: AlpacaSnapshot | undefined
): { change: number; changePct: number } | null {
    const price = snapshotPrice(snapshot)
    const previousClose = snapshot?.prevDailyBar?.c
    if (price === null || typeof previousClose !== "number" || previousClose <= 0) return null
    const change = price - previousClose
    return { change, changePct: (change / previousClose) * 100 }
}

// MARK: - Bars

export type BarTimeframe = "1Min" | "5Min" | "15Min" | "30Min" | "1Hour" | "1Day" | "1Week"

/**
 * How corporate actions are folded into historical prices.
 *
 * "split" is the default and what every chart in the app has always used: a
 * 10-for-1 split does not draw as a 90% crash. It deliberately leaves
 * dividends out, which is right for a price chart and wrong for a backtest.
 * Measured on KO over the available window, price return is +92.5% and total
 * return is +130.0%, so a "what would I have made" answer built on split-only
 * bars understates the truth by 37 percentage points.
 *
 * "all" adds dividend adjustment, giving total return. Ask for it where the
 * question is about money earned rather than price drawn.
 */
export type BarAdjustment = "split" | "all"

/** Bars for one symbol, oldest first. */
export async function bars(
    symbol: string,
    timeframe: BarTimeframe,
    start: Date,
    limit: number,
    revalidate = 60,
    adjustment: BarAdjustment = "split"
): Promise<AlpacaBar[]> {
    const crypto = isCryptoSymbol(symbol)
    const url = crypto
        ? `${DATA_BASE}/v1beta3/crypto/us/bars?symbols=${encodeURIComponent(toAlpacaCrypto(symbol))}` +
          `&timeframe=${timeframe}&start=${start.toISOString()}&limit=${limit}`
        : `${DATA_BASE}/v2/stocks/bars?symbols=${encodeURIComponent(symbol)}` +
          `&timeframe=${timeframe}&start=${start.toISOString()}&limit=${limit}&feed=${FEED}&adjustment=${adjustment}`

    const json = await get<{ bars?: Record<string, AlpacaBar[]> }>(url, revalidate)
    const key = crypto ? toAlpacaCrypto(symbol) : symbol
    return json?.bars?.[key] ?? []
}

/** Bars for several symbols in one request, keyed by the caller's symbol form. */
export async function multiBars(
    symbols: string[],
    timeframe: BarTimeframe,
    start: Date,
    limit: number,
    revalidate = 900
): Promise<Record<string, AlpacaBar[]>> {
    if (symbols.length === 0) return {}
    const equities = symbols.filter((symbol) => !isCryptoSymbol(symbol))
    const cryptos = symbols.filter(isCryptoSymbol)
    const out: Record<string, AlpacaBar[]> = {}

    if (equities.length > 0) {
        const url =
            `${DATA_BASE}/v2/stocks/bars?symbols=${encodeURIComponent(equities.join(","))}` +
            `&timeframe=${timeframe}&start=${start.toISOString()}&limit=${limit}&feed=${FEED}&adjustment=split`
        const json = await get<{ bars?: Record<string, AlpacaBar[]> }>(url, revalidate)
        for (const [symbol, list] of Object.entries(json?.bars ?? {})) out[symbol] = list
    }

    if (cryptos.length > 0) {
        const pairs = cryptos.map(toAlpacaCrypto)
        const url =
            `${DATA_BASE}/v1beta3/crypto/us/bars?symbols=${encodeURIComponent(pairs.join(","))}` +
            `&timeframe=${timeframe}&start=${start.toISOString()}&limit=${limit}`
        const json = await get<{ bars?: Record<string, AlpacaBar[]> }>(url, revalidate)
        for (const [pair, list] of Object.entries(json?.bars ?? {})) out[fromAlpacaCrypto(pair)] = list
    }

    return out
}

// MARK: - Assets (names and search)

export type AlpacaAsset = {
    symbol: string
    name: string
    exchange: string
    class: string
    tradable: boolean
    status: string
}

/** One asset, for its display name. */
export async function asset(symbol: string, revalidate = 86400): Promise<AlpacaAsset | null> {
    return get<AlpacaAsset>(`${TRADING_BASE}/v2/assets/${encodeURIComponent(symbol)}`, revalidate)
}

/**
 * Every active, tradable US equity. Cached for a day — it's a large list and it
 * barely moves — and used for symbol search, which Alpaca has no query endpoint
 * for.
 */
export async function activeAssets(revalidate = 86400): Promise<AlpacaAsset[]> {
    const json = await get<AlpacaAsset[]>(
        `${TRADING_BASE}/v2/assets?status=active&asset_class=us_equity`,
        revalidate
    )
    return Array.isArray(json) ? json : []
}

// MARK: - News

export type AlpacaNews = {
    id: number
    headline: string
    summary: string
    author: string
    source: string
    url: string
    images?: { size: string; url: string }[]
    symbols: string[]
    created_at: string
    updated_at: string
}

export async function news(
    { symbols, limit = 20 }: { symbols?: string[]; limit?: number },
    revalidate = 600
): Promise<AlpacaNews[]> {
    const params = new URLSearchParams({ limit: String(limit), sort: "desc", exclude_contentless: "true" })
    if (symbols && symbols.length > 0) params.set("symbols", symbols.join(","))
    const json = await get<{ news?: AlpacaNews[] }>(
        `${DATA_BASE}/v1beta1/news?${params.toString()}`,
        revalidate
    )
    return json?.news ?? []
}

// MARK: - Screener

export type AlpacaMover = { symbol: string; percent_change: number; change: number; price: number }

export async function movers(
    top = 10,
    revalidate = 300
): Promise<{ gainers: AlpacaMover[]; losers: AlpacaMover[] }> {
    const json = await get<{ gainers?: AlpacaMover[]; losers?: AlpacaMover[] }>(
        `${DATA_BASE}/v1beta1/screener/stocks/movers?top=${top}`,
        revalidate
    )
    return { gainers: json?.gainers ?? [], losers: json?.losers ?? [] }
}

export type AlpacaActive = { symbol: string; volume: number; trade_count: number }

export async function mostActives(
    top = 50,
    by: "volume" | "trades" = "volume",
    revalidate = 300
): Promise<AlpacaActive[]> {
    const json = await get<{ most_actives?: AlpacaActive[] }>(
        `${DATA_BASE}/v1beta1/screener/stocks/most-actives?by=${by}&top=${top}`,
        revalidate
    )
    return json?.most_actives ?? []
}

// MARK: - Corporate actions

/** One announced cash dividend. Dates are "YYYY-MM-DD". */
export type AlpacaCashDividend = {
    symbol: string
    /** Amount per share. Alpaca calls it `rate`. */
    rate: number
    ex_date?: string
    record_date?: string
    payable_date?: string
    process_date?: string
    /** "cash_dividend" for a regular one, "special_cash_dividend" otherwise. */
    special?: boolean
}

/**
 * Cash dividends for a set of symbols over a window.
 *
 * This is the only source in reach that carries dividend DATES. The SEC's XBRL
 * data has the amounts (94 quarters of them for KO) but stamps each one with a
 * fiscal period rather than an ex or payable date, so it can total a year and
 * cannot place a single dot on a calendar. Alpaca's corporate actions carry
 * ex_date, record_date and payable_date, and asking for a window that ends in
 * the future returns dividends that have been declared but not yet paid, which
 * is the upcoming half.
 *
 * Paged: the endpoint returns a next_page_token and the app asks for several
 * holdings over a year, so a single page would silently truncate the oldest
 * or newest depending on order. This is the bug that has bitten this codebase
 * four times in other routes; it is not being written a fifth time.
 */
export async function cashDividends(
    symbols: string[],
    start: Date,
    end: Date,
    revalidate = 21600
): Promise<AlpacaCashDividend[]> {
    const wanted = [...new Set(symbols.map((s) => s.toUpperCase().trim()).filter(Boolean))]
    if (wanted.length === 0) return []

    const day = (d: Date) => d.toISOString().slice(0, 10)
    const out: AlpacaCashDividend[] = []
    let pageToken: string | undefined
    // A guard, not an expectation: five pages is far more than a handful of
    // holdings over a couple of years, and it stops a malformed token from
    // looping forever.
    for (let page = 0; page < 5; page++) {
        const params = new URLSearchParams({
            symbols: wanted.join(","),
            types: "cash_dividend",
            start: day(start),
            end: day(end),
            limit: "1000",
        })
        if (pageToken) params.set("page_token", pageToken)
        const json = await get<{
            corporate_actions?: { cash_dividends?: AlpacaCashDividend[] }
            next_page_token?: string | null
        }>(`${DATA_BASE}/v1/corporate-actions?${params.toString()}`, revalidate)
        if (!json) break
        out.push(...(json.corporate_actions?.cash_dividends ?? []))
        if (!json.next_page_token) break
        pageToken = json.next_page_token
    }
    return out
}

lib/quotes.ts:
// Shared live-quote lookup. Alpaca is the only provider: equities come from
// the stock snapshots endpoint, crypto pairs from the crypto one.
//
// A quote is only returned when Alpaca actually has one. Callers render "—"
// otherwise rather than showing a figure nobody can stand behind.

import {
    asset,
    cryptoSnapshots,
    isCryptoSymbol,
    snapshotChange,
    snapshotPrice,
    activeAssets,
    stockSnapshots,
} from "@/lib/alpaca"

export type LiveQuote = {
    price: number
    /** Timestamp of the observation used for `price`. */
    asOf: string | null
    /** True when provider has no timestamp or last observation is over 7 days old. */
    isStale: boolean
    /**
     * The day's move, or null when Alpaca has no previous close to measure
     * against. Nullable rather than zero: these used to fall back to 0, which
     * states that a stock finished the day exactly flat. BRK.A is the live
     * example. It trades a few shares a day, IEX carries no daily bar for it
     * at all, and the row read "$477,207.28, 0.00%" as though we had checked.
     * A price we have and a move we do not are different facts.
     */
    change: number | null
    changePct: number | null
    /** Instrument name, when the assets endpoint knows it. */
    name: string | null
}

// A week tolerates weekends, exchange holidays and quiet IEX trading while
// rejecting retired symbols whose snapshots keep their final trade forever.
const MAX_QUOTE_AGE_MS = 7 * 24 * 60 * 60 * 1000

/**
 * Current Alpaca listings, or null when the trading-API catalogue is
 * unavailable. Callers must fall back to timestamp checks on null; an empty
 * provider response must never be interpreted as "everything delisted".
 */
export async function activeSymbolSet(revalidate = 900): Promise<Set<string> | null> {
    const assets = await activeAssets(revalidate)
    if (assets.length === 0) return null
    return new Set(assets.filter((asset) => asset.status.toLowerCase() === "active").map((asset) => asset.symbol.toUpperCase()))
}

function observationTime(snapshot: {
    latestTrade?: { t: string }
    minuteBar?: { t: string }
    dailyBar?: { t: string }
    prevDailyBar?: { t: string }
} | undefined): string | null {
    return snapshot?.latestTrade?.t ?? snapshot?.minuteBar?.t ?? snapshot?.dailyBar?.t ?? snapshot?.prevDailyBar?.t ?? null
}

function isStale(asOf: string | null, now = Date.now()): boolean {
    if (!asOf) return true
    const time = Date.parse(asOf)
    return !Number.isFinite(time) || time > now + 5 * 60 * 1000 || now - time > MAX_QUOTE_AGE_MS
}

/**
 * Live quotes for a batch of symbols, keyed by the caller's own symbol form.
 * Equities and crypto are fetched in one request each rather than one per
 * symbol.
 */
export async function fetchQuotes(
    symbols: string[],
    revalidate = 60
): Promise<Record<string, LiveQuote>> {
    const wanted = symbols.map((symbol) => symbol.toUpperCase().trim()).filter(Boolean)
    if (wanted.length === 0) return {}

    const equities = wanted.filter((symbol) => !isCryptoSymbol(symbol))
    const cryptos = wanted.filter(isCryptoSymbol)

    const [equitySnapshots, cryptoSnaps] = await Promise.all([
        stockSnapshots(equities, revalidate),
        cryptoSnapshots(cryptos, revalidate),
    ])
    const snapshots = { ...equitySnapshots, ...cryptoSnaps }

    const out: Record<string, LiveQuote> = {}
    for (const symbol of wanted) {
        const snapshot = snapshots[symbol]
        const price = snapshotPrice(snapshot)
        if (price === null) continue
        const move = snapshotChange(snapshot)
        const asOf = observationTime(snapshot)
        out[symbol] = {
            price,
            asOf,
            isStale: isStale(asOf),
            change: move?.change ?? null,
            changePct: move?.changePct ?? null,
            name: null,
        }
    }
    return out
}

/**
 * A live price for one instrument, or null when Alpaca has none. The name costs
 * a second (day-cached) call, so it's only looked up for equities, which is
 * where Alpaca has one.
 */
export async function fetchQuote(symbol: string, revalidate = 60): Promise<LiveQuote | null> {
    const upper = symbol.toUpperCase().trim()
    const quotes = await fetchQuotes([upper], revalidate)
    const quote = quotes[upper]
    if (!quote) return null
    if (isCryptoSymbol(upper)) return quote
    const info = await asset(upper)
    return { ...quote, name: info?.name ?? null }
}

lib/sec.ts:
/**
 * Talking to the SEC, and being honest about it when it doesn't answer.
 *
 * Five routes read EDGAR. Each one used to collapse every possible failure into
 * the same empty array: a symbol that genuinely doesn't file, a filer that
 * doesn't tag a line, a 403 because our User-Agent was rejected, a 429 because
 * we were rate-limited, and a socket that never opened all produced
 * `{ items: [] }`. The screens above them then hid themselves, so a rejected
 * request rendered as "this person has never traded" — a claim we hadn't earned
 * and, on Vercel, one that was wrong for every symbol at once.
 *
 * So every SEC read returns a status:
 *
 *   ok            we have the data
 *   no-data       the SEC answered, and there is genuinely nothing here
 *   unavailable   the SEC refused us or couldn't be reached — we don't know
 *
 * "no-data" and "unavailable" are different sentences to a reader, and only the
 * first is safe to render as an empty section.
 */

export type SourceStatus = "ok" | "no-data" | "unavailable"

export type SecResult<T> =
    | { status: "ok"; data: T }
    | { status: "no-data"; reason: string }
    | { status: "unavailable"; reason: string }

/**
 * The SEC blocks callers who don't identify themselves with a contact that
 * actually receives mail. The fallback is a real address, but a deployment
 * serving real traffic should set SEC_CONTACT to its own — a shared default
 * across every deployment is what gets a User-Agent rate-limited.
 */
export const SEC_HEADERS: Record<string, string> = {
    "User-Agent": process.env.SEC_CONTACT ?? "FinnaCalc help@finnacalc.com",
    Accept: "application/json",
}

/** True once we've logged the SEC_CONTACT hint, so a bad deploy logs it once. */
let warnedAboutContact = false

/**
 * Turns an HTTP response into a status.
 *
 * 404 is the only code that means "nothing here": EDGAR returns it for a CIK
 * with no filings of that kind. Everything else non-2xx means the SEC declined
 * to tell us, which is not the same answer and must not be shown as one.
 */
function classify(status: number, url: string): { status: "no-data" | "unavailable"; reason: string } {
    if (status === 404) {
        return { status: "no-data", reason: "The SEC has no filing at this address." }
    }
    if (status === 401 || status === 403) {
        if (!warnedAboutContact) {
            warnedAboutContact = true
            console.warn(
                `[sec] ${status} from ${url}. The SEC rejects callers it can't identify — ` +
                    `set SEC_CONTACT to "YourApp you@example.com" in this environment.`
            )
        }
        return { status: "unavailable", reason: "The SEC declined the request." }
    }
    if (status === 429) {
        return { status: "unavailable", reason: "The SEC is rate-limiting us right now." }
    }
    return { status: "unavailable", reason: `The SEC returned an error (HTTP ${status}).` }
}

async function read<T>(
    url: string,
    revalidate: number,
    parse: (response: Response) => Promise<T>
): Promise<SecResult<T>> {
    let response: Response
    try {
        response = await fetch(url, { headers: SEC_HEADERS, next: { revalidate } })
    } catch {
        // No response at all: DNS, TLS, a blocked egress route. We know nothing
        // about whether the filing exists.
        return { status: "unavailable", reason: "Couldn't reach the SEC." }
    }

    if (!response.ok) return classify(response.status, url)

    try {
        return { status: "ok", data: await parse(response) }
    } catch {
        // A 200 whose body doesn't parse is the SEC serving us something else —
        // an error page, a truncated response. Still not "nothing here".
        return { status: "unavailable", reason: "The SEC's response couldn't be read." }
    }
}

export function secJson<T = any>(url: string, revalidate: number): Promise<SecResult<T>> {
    return read<T>(url, revalidate, (response) => response.json() as Promise<T>)
}

export function secText(url: string, revalidate: number): Promise<SecResult<string>> {
    return read<string>(url, revalidate, (response) => response.text())
}

export function secBuffer(url: string, revalidate: number): Promise<SecResult<Buffer>> {
    return read<Buffer>(url, revalidate, async (response) =>
        Buffer.from(await response.arrayBuffer())
    )
}

/**
 * The CIK for a ticker, or why we don't have one.
 *
 * Distinguishes "this ticker isn't in the SEC's map" — true of most ETFs and
 * foreign listings — from "we couldn't read the map", which tells us nothing
 * about the ticker at all.
 */
export async function cikFor(symbol: string): Promise<SecResult<string>> {
    // The ticker map moves slowly, so it's cached far longer than the filings.
    const result = await secJson<Record<string, { cik_str: number; ticker: string }>>(
        "https://www.sec.gov/files/company_tickers.json",
        604800
    )
    if (result.status !== "ok") return result

    // Class shares are written BRK.B by people and by quote feeds, but the SEC
    // writes them BRK-B.
    const candidates = [symbol, symbol.replace(/\./g, "-")]
    const hit = Object.values(result.data).find((company) => candidates.includes(company.ticker))
    if (!hit) {
        return {
            status: "no-data",
            reason: `${symbol} isn't in the SEC's ticker-to-company map, so we can't look up its filings.`,
        }
    }
    return { status: "ok", data: String(hit.cik_str).padStart(10, "0") }
}

/**
 * What a route reports alongside its (possibly empty) payload.
 *
 * `reason` is written to be shown to a reader, so it names what happened
 * without naming environment variables — the operator's hint goes to the server
 * log instead. It's null when the status is "ok".
 */
export type SourceReport = { status: SourceStatus; reason: string | null }

export const OK: SourceReport = { status: "ok", reason: null }

export function reportOf(result: SecResult<unknown>): SourceReport {
    return result.status === "ok" ? OK : { status: result.status, reason: result.reason }
}

lib/investing/fundamentals.ts:
/**
 * The Key Stats figures, derived from a company's own SEC filings.
 *
 * WHY THIS EXISTS
 * ---------------
 * /api/stock returns a `stats` block and an `overview` block that the iOS Key
 * Stats section reads row by row. Since the move to Alpaca every field in them
 * has been null: Alpaca prices what trades and publishes no fundamentals. The
 * section still ships, and has been rendering three rows (price and the 52-week
 * pair) out of twelve.
 *
 * Everything here comes from the same company facts document /api/statements
 * already downloads, at the same 24h revalidate, so the two routes share one
 * cache entry rather than pulling a 4 MB file twice.
 *
 * WHAT THIS IS NOT
 * ----------------
 * Not a fundamentals vendor. Filings land quarterly and late, so a margin here
 * is the last fiscal year's, not the last twelve weeks'. Every function returns
 * null rather than a fallback, and the app hides a row whose value is null.
 * When a real fundamentals feed is bought, delete this file and fill the same
 * field names from it: nothing above this layer knows where the numbers came
 * from.
 *
 * THE TRAPS, ALL THREE MEASURED
 * -----------------------------
 * 1. Share counts. dei:EntityCommonStockSharesOutstanding is the right concept,
 *    a cover-page count as of a date just before filing. But the XBRL APIs only
 *    aggregate facts that "apply to the entire filing entity", which drops
 *    every dimensioned per-share-class fact. So multi-class issuers either
 *    carry nothing or carry poison: GOOGL and META have no such fact at all,
 *    Berkshire's newest is from 2011, Fox's is the literal value 1, Paramount's
 *    is 0. A market cap built on those prints Berkshire at about $470M against
 *    about $1.1T. Hence `plausibleShareCount`, which demands a recent date and
 *    a sane magnitude and returns null otherwise. A hidden row beats a wrong
 *    one.
 *
 * 2. Trailing twelve months. There is no fourth 10-Q: a filer goes from Q3 to
 *    the 10-K. So the last four discrete quarters are not sitting there to be
 *    summed, and summing the four that ARE there silently substitutes a
 *    year-old quarter for the missing one. Apple comes out at 8.44 that way
 *    against a true 8.72. `trailingTwelveMonths` uses the identity that does
 *    hold: last full year, plus this year so far, minus the same span of last
 *    year.
 *
 * 3. Which tag a company uses for a line is per-company and changes mid-life.
 *    Apple's us-gaap:Revenues stops in 2018 with 11 points; its real revenue
 *    is under RevenueFromContractWithCustomerExcludingAssessedTax now and
 *    SalesRevenueNet before that. Tags are therefore merged across a list,
 *    newest filing winning, exactly as /api/statements does.
 */

import { cikFor, secJson, type SecResult } from "@/lib/sec"

/** Shared with /api/statements so both routes hit one cached document. */
export const FACTS_REVALIDATE = 86400

type Fact = {
    start?: string
    end: string
    val: number
    form?: string
    fp?: string
    filed?: string
}

export type Fundamentals = {
    sharesOutstanding: number | null
    marketCap: number | null
    epsTTM: number | null
    peRatio: number | null
    netMargin: number | null
    grossMargin: number | null
    revenueGrowth: number | null
    dividendYield: number | null
    /** Kept alongside the yield so a cached entry can be re-priced. */
    dividendsPerShareTTM: number | null
    /** Where the figures stop, so a caller can say "as of". */
    fiscalYear: number | null
    sharesAsOf: string | null
}

export const NO_FUNDAMENTALS: Fundamentals = {
    sharesOutstanding: null,
    marketCap: null,
    epsTTM: null,
    peRatio: null,
    netMargin: null,
    grossMargin: null,
    revenueGrowth: null,
    dividendYield: null,
    dividendsPerShareTTM: null,
    fiscalYear: null,
    sharesAsOf: null,
}

const REVENUE_TAGS = [
    "RevenueFromContractWithCustomerExcludingAssessedTax",
    "RevenueFromContractWithCustomerIncludingAssessedTax",
    "Revenues",
    "SalesRevenueNet",
    "SalesRevenueGoodsNet",
]
const NET_INCOME_TAGS = ["NetIncomeLoss", "ProfitLoss"]
const GROSS_PROFIT_TAGS = ["GrossProfit"]
const EPS_TAGS = ["EarningsPerShareDiluted"]
const DIVIDEND_PER_SHARE_TAGS = [
    "CommonStockDividendsPerShareDeclared",
    "CommonStockDividendsPerShareCashPaid",
]
/** Point-in-time counts only. A weighted average is the EPS denominator and
 *  is inflated by options and convertibles; it is never a market-cap input. */
const SHARE_COUNT_TAGS = ["CommonStockSharesOutstanding"]

/** The money or per-share facts for one tag, never whichever unit came first. */
const CURRENCY_KEY = /^[A-Z]{3}$/
const PER_SHARE_KEY = /^[A-Z]{3}\/shares$/

function unitsOf(node: any): Fact[] {
    const units = (node?.units ?? {}) as Record<string, Fact[]>
    const keys = Object.keys(units)
    if (!keys.length) return []
    const longest = (list: string[]) => list.sort((a, b) => units[b].length - units[a].length)[0]
    const money = keys.filter((k) => CURRENCY_KEY.test(k))
    if (money.length) return units[longest(money)]
    const perShare = keys.filter((k) => PER_SHARE_KEY.test(k))
    if (perShare.length) return units[longest(perShare)]
    if (units.shares) return units.shares
    return Object.values(units).sort((a, b) => b.length - a.length)[0] ?? []
}

/**
 * The currency the filer reports in.
 *
 * It matters because `price` is US dollars off a US exchange, and half the
 * figures below divide one by the other. ASML files us-gaap tags in EUROS:
 * its EPS is euros, its price is dollars, and price divided by EPS was
 * printing a P/E wrong by the whole exchange rate.
 */
function reportingCurrency(facts: Record<string, any>): string {
    const tally = new Map<string, number>()
    for (const tag of ["Assets", "Revenues", "Liabilities", "StockholdersEquity",
                       "NetIncomeLoss", "ProfitLoss"]) {
        const units = (facts[tag]?.units ?? {}) as Record<string, Fact[]>
        for (const [key, list] of Object.entries(units)) {
            if (!CURRENCY_KEY.test(key)) continue
            tally.set(key, (tally.get(key) ?? 0) + list.length)
        }
    }
    return [...tally.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? "USD"
}

/**
 * Every annual report form, and their amendments. 10-K is the domestic filer,
 * 20-F the foreign private issuer, 40-F the Canadian MJDS filer. Amendments
 * count because a restated year should displace the one it restates.
 */
const ANNUAL_FORMS = new Set(["10-K", "10-K/A", "20-F", "20-F/A", "40-F", "40-F/A"])

function isAnnualForm(u: Fact): boolean {
    return u.form !== undefined && ANNUAL_FORMS.has(u.form)
}

/** Whole months a duration fact covers. */
function months(u: Fact): number {
    if (!u.start) return 0
    return (
        (Number(u.end.slice(0, 4)) - Number(u.start.slice(0, 4))) * 12 +
        (Number(u.end.slice(5, 7)) - Number(u.start.slice(5, 7)))
    )
}

/**
 * The most recent annual value for a line, and the one before it.
 *
 * Merged across tags with earlier tags winning a tie, and restatements
 * resolved by filing date, so a company that changed tags mid-history keeps
 * one continuous series. Keyed on the period's END, not on `fy`: in company
 * facts `fy` describes the REPORT a number appeared in, so all three
 * comparative years inside one 10-K carry that 10-K's year.
 */
function annualSeries(facts: Record<string, any>, tags: string[]): Map<string, number> {
    const merged = new Map<string, number>()
    for (const tag of tags) {
        if (!facts[tag]) continue
        const best = new Map<string, Fact>()
        for (const u of unitsOf(facts[tag])) {
            if (!isAnnualForm(u)) continue
            if (u.start && months(u) < 11) continue
            const prev = best.get(u.end)
            if (!prev || (u.filed ?? "") > (prev.filed ?? "")) best.set(u.end, u)
        }
        for (const [end, fact] of best) if (!merged.has(end)) merged.set(end, fact.val)
    }
    return merged
}

/** Annual values newest first, as [periodEnd, value]. */
function newestFirst(series: Map<string, number>): [string, number][] {
    return [...series.entries()].sort((a, b) => (a[0] < b[0] ? 1 : -1))
}

/**
 * A share count worth multiplying a price by.
 *
 * The XBRL aggregation drops per-share-class facts, and what a multi-class
 * issuer leaves behind is worse than nothing: a count from 2011, or the
 * literal 1, or 0. Two gates, both cheap:
 *
 *   RECENT   the count must be dated within 400 days. Cover-page counts are
 *            refreshed every 10-Q, so anything older means the current one was
 *            dimensioned away.
 *   SANE     at least a hundred thousand shares. A public company with fewer
 *            has a share price in the millions; the real cases are Fox's 1 and
 *            Paramount's 0.
 *
 * Fails closed. Every caller renders an em dash on null.
 */
function plausibleShareCount(u: Fact | undefined, today: Date): number | null {
    if (!u) return null
    if (!Number.isFinite(u.val) || u.val < 100_000) return null
    const age = (today.getTime() - Date.parse(u.end + "T00:00:00Z")) / 86_400_000
    if (!Number.isFinite(age) || age > 400 || age < -30) return null
    return u.val
}

/**
 * Shares outstanding, preferring the cover-page count.
 *
 * dei:EntityCommonStockSharesOutstanding is dated a few days before the filing
 * and is the closest thing to "right now" in the document. us-gaap's
 * CommonStockSharesOutstanding is the balance-sheet date, weeks older, and is
 * the fallback rather than the first choice.
 */
function sharesOutstanding(
    dei: Record<string, any>,
    gaap: Record<string, any>,
    today: Date
): { value: number; asOf: string } | null {
    const candidates: Fact[] = []
    const cover = unitsOf(dei?.EntityCommonStockSharesOutstanding)
    if (cover.length) candidates.push(...cover.filter((u) => !u.start))
    for (const tag of SHARE_COUNT_TAGS) {
        if (gaap?.[tag]) candidates.push(...unitsOf(gaap[tag]).filter((u) => !u.start))
    }
    // Cover-page facts are pushed first, so a tie on date keeps the cover count.
    const newest = candidates.sort((a, b) => (a.end < b.end ? 1 : -1))[0]
    const value = plausibleShareCount(newest, today)
    return value === null ? null : { value, asOf: newest!.end }
}

/**
 * Trailing twelve months for a duration line.
 *
 * Not a sum of four quarters, because the fourth does not exist as a filed
 * period. The identity used instead:
 *
 *     TTM = last full fiscal year
 *         + the current year to date
 *         − the same year-to-date span of the prior year
 *
 * Year-to-date facts are exactly what a 10-Q reports: a Q3 filing carries a
 * nine-month duration. The prior year's matching span is found by month count,
 * not by `fp`, since `fp` describes the report rather than the period.
 *
 * Returns the annual figure unchanged when the year is fresh and no interim
 * period has been filed yet, which is correct: twelve months ago IS the year.
 */
function trailingTwelveMonths(facts: Record<string, any>, tags: string[]): number | null {
    const annual = newestFirst(annualSeries(facts, tags))
    if (!annual.length) return null
    const [lastYearEnd, lastYearValue] = annual[0]

    // Cumulative interim periods, newest first, that start after the last full
    // year ended. A 10-Q's year-to-date always begins the day the year did.
    const interim: Fact[] = []
    for (const tag of tags) {
        if (!facts[tag]) continue
        for (const u of unitsOf(facts[tag])) {
            if (isAnnualForm(u) || !u.start) continue
            if (u.start <= lastYearEnd) continue
            const span = months(u)
            if (span < 2 || span > 11) continue
            interim.push(u)
        }
    }
    if (!interim.length) return lastYearValue

    // The longest span wins, and among equals the most recently filed, so a
    // restated nine months beats the original.
    // Longest span first, and among equal spans the most recently filed, so a
    // restated nine months beats the original nine months.
    interim.sort((a, b) => months(b) - months(a) || (b.filed ?? "").localeCompare(a.filed ?? ""))
    const current = interim[0]
    const span = months(current)

    // The same span one year earlier, so the subtraction removes exactly what
    // the addition put in.
    let prior: Fact | undefined
    for (const tag of tags) {
        if (!facts[tag]) continue
        for (const u of unitsOf(facts[tag])) {
            if (isAnnualForm(u) || !u.start) continue
            if (months(u) !== span) continue
            if (u.end >= current.start!) continue
            if (Number(lastYearEnd.slice(0, 4)) - Number(u.end.slice(0, 4)) > 1) continue
            if (!prior || u.end > prior.end || (u.end === prior.end && (u.filed ?? "") > (prior.filed ?? "")))
                prior = u
        }
    }
    if (!prior) return lastYearValue
    return lastYearValue + current.val - prior.val
}

function ratio(numerator: number | null, denominator: number | null): number | null {
    if (numerator === null || denominator === null) return null
    if (!Number.isFinite(numerator) || !Number.isFinite(denominator)) return null
    // A percentage of a zero or negative base is not a percentage. A company
    // whose losses shrank would otherwise print as negative growth.
    if (denominator <= 0) return null
    return (numerator / denominator) * 100
}

/**
 * Everything Key Stats needs, from one company facts document and a live price.
 *
 * `price` comes from Alpaca and is the only input here that is current; every
 * other figure is as filed. Market cap and the P/E are therefore a live price
 * against a filed denominator, which is what those ratios are everywhere.
 */
export function fundamentalsFrom(doc: any, price: number | null, now: Date = new Date()): Fundamentals {
    const gaap = doc?.facts?.["us-gaap"]
    const dei = doc?.facts?.dei
    if (!gaap) return NO_FUNDAMENTALS

    const revenue = newestFirst(annualSeries(gaap, REVENUE_TAGS))
    const netIncome = newestFirst(annualSeries(gaap, NET_INCOME_TAGS))
    const grossProfit = newestFirst(annualSeries(gaap, GROSS_PROFIT_TAGS))

    const latestRevenue = revenue[0]?.[1] ?? null
    const priorRevenue = revenue[1]?.[1] ?? null
    const latestYearEnd = revenue[0]?.[0] ?? netIncome[0]?.[0] ?? null

    // Net income and gross profit are only comparable to revenue from the same
    // period, so they are matched on the period end rather than taken as
    // "whichever is newest".
    const netIncomeSameYear =
        latestYearEnd !== null ? netIncome.find(([end]) => end === latestYearEnd)?.[1] ?? null : null
    const grossProfitSameYear =
        latestYearEnd !== null ? grossProfit.find(([end]) => end === latestYearEnd)?.[1] ?? null : null

    const shares = sharesOutstanding(dei, gaap, now)
    const epsTTM = trailingTwelveMonths(gaap, EPS_TAGS)
    const dividendsTTM = trailingTwelveMonths(gaap, DIVIDEND_PER_SHARE_TAGS)

    const usablePrice = price !== null && Number.isFinite(price) && price > 0 ? price : null

    // A filer reporting in its own currency cannot be divided by a US dollar
    // price. The ratios below that mix the two are withheld rather than
    // printed wrong: ASML's P/E was out by the whole EUR/USD rate, roughly
    // 15%, and its dividend yield with it. The pure ratios, margins and
    // growth, divide same-currency figures and are unaffected.
    const currency = reportingCurrency(gaap)
    const comparableToPrice = currency === "USD"

    return {
        sharesOutstanding: shares?.value ?? null,
        sharesAsOf: shares?.asOf ?? null,
        marketCap: shares && usablePrice ? shares.value * usablePrice : null,
        // Withheld rather than mislabelled when it is not in dollars: every
        // reader of this field, the Key Stats row and the portfolio's
        // "earnings behind your shares", treats it as dollars per share.
        epsTTM: comparableToPrice ? epsTTM : null,
        // A negative or zero EPS has no meaningful price-to-earnings multiple;
        // the convention everywhere is to omit it rather than print a negative.
        peRatio:
            comparableToPrice && usablePrice && epsTTM !== null && epsTTM > 0
                ? usablePrice / epsTTM
                : null,
        netMargin: ratio(netIncomeSameYear, latestRevenue),
        grossMargin: ratio(grossProfitSameYear, latestRevenue),
        revenueGrowth:
            latestRevenue !== null && priorRevenue !== null && priorRevenue > 0
                ? (latestRevenue / priorRevenue - 1) * 100
                : null,
        dividendYield:
            comparableToPrice && usablePrice && dividendsTTM !== null && dividendsTTM > 0
                ? (dividendsTTM / usablePrice) * 100
                : null,
        dividendsPerShareTTM: comparableToPrice ? dividendsTTM : null,
        fiscalYear: latestYearEnd ? Number(latestYearEnd.slice(0, 4)) : null,
    }
}

/**
 * The derived figures per CIK, so a warm instance reads the 4 MB document once.
 *
 * Next's data cache does not store a fetch response over 2 MB, and company
 * facts is 3.8 MB for Apple and 7.9 MB for JPMorgan. Without this every stock
 * page view on a large filer would pull the whole document again, against a
 * limit of ten requests per second shared across the entire deployment.
 *
 * What is kept is the DERIVED object, ten numbers, not the document. So the
 * memory cost is bytes rather than megabytes and the 2 MB ceiling stops
 * mattering. Small filers stay inside Next's cache as well and get both.
 *
 * Deliberately a plain Map and not a KV store. It is per-instance and empty
 * after a cold start, which is the honest limit of it: this reduces repeat
 * work, it does not guarantee a single fetch across a fleet. It also needs no
 * service, no credentials and no configuration, which is what makes it
 * shippable now. If stock pages ever carry enough traffic for the SEC to
 * rate-limit us anyway, the fix is a real shared cache in front of `secJson`,
 * and every route benefits rather than only this one.
 *
 * Everything below is priced against the live quote OUTSIDE the cache, so a
 * cached entry never serves a stale market cap or P/E.
 */
type CacheEntry = { at: number; value: Fundamentals }
const derived = new Map<string, CacheEntry>()
const CACHE_TTL_MS = FACTS_REVALIDATE * 1000
/** Filings do not change often; this is a working set, not a database. */
const CACHE_MAX = 500

function cached(cik: string, now: number): Fundamentals | null {
    const hit = derived.get(cik)
    if (!hit) return null
    if (now - hit.at > CACHE_TTL_MS) {
        derived.delete(cik)
        return null
    }
    // Re-inserted so the eviction below drops the least recently READ, not the
    // least recently written.
    derived.delete(cik)
    derived.set(cik, hit)
    return hit.value
}

function remember(cik: string, value: Fundamentals, now: number): void {
    derived.set(cik, { at: now, value })
    while (derived.size > CACHE_MAX) {
        const oldest = derived.keys().next()
        if (oldest.done) break
        derived.delete(oldest.value)
    }
}

/**
 * Everything except the price, which is why this is cacheable at all.
 *
 * Splitting the filed half from the priced half is the whole trick: the filed
 * half changes quarterly and the priced half changes every second, so they
 * cannot share a lifetime.
 */
function priced(base: Fundamentals, price: number | null): Fundamentals {
    const usable = price !== null && Number.isFinite(price) && price > 0 ? price : null
    if (!usable) return { ...base, marketCap: null, peRatio: null, dividendYield: base.dividendYield }
    return {
        ...base,
        marketCap: base.sharesOutstanding !== null ? base.sharesOutstanding * usable : null,
        peRatio: base.epsTTM !== null && base.epsTTM > 0 ? usable / base.epsTTM : null,
        dividendYield: base.dividendsPerShareTTM !== null && base.dividendsPerShareTTM > 0
            ? (base.dividendsPerShareTTM / usable) * 100
            : null,
    }
}

/** Fetch and derive in one call. Never throws; an unreachable SEC is null. */
export async function fundamentalsFor(symbol: string, price: number | null): Promise<Fundamentals> {
    const cik = await cikFor(symbol)
    if (cik.status !== "ok") return NO_FUNDAMENTALS

    const now = Date.now()
    const hit = cached(cik.data, now)
    if (hit) return priced(hit, price)

    const facts: SecResult<any> = await secJson<any>(
        `https://data.sec.gov/api/xbrl/companyfacts/CIK${cik.data}.json`,
        FACTS_REVALIDATE
    )
    // A refusal is not cached. "The SEC rate-limited us" must not become this
    // symbol's answer for the next day.
    if (facts.status !== "ok") return NO_FUNDAMENTALS

    const base = fundamentalsFrom(facts.data, null)
    remember(cik.data, base, now)
    return priced(base, price)
}

lib/investing/names.ts:
/**
 * Ticker to company name.
 *
 * WHY THIS EXISTS
 * ---------------
 * Every stock page was titled with its own ticker: "AAPL" on the name line and
 * "AAPL" again on the ticker line under it. The screener and movers lists had
 * the same problem, showing the symbol where a company belongs. The intended
 * source was Alpaca's asset record, which comes back empty in production, so
 * the code fell through to `|| symbol` everywhere and nobody noticed because
 * a ticker looks like a plausible name.
 *
 * WHERE THE NAMES COME FROM, AND WHY IT IS FINE TO USE THEM
 * --------------------------------------------------------
 * The SEC publishes company_tickers.json: every registered US issuer's ticker
 * paired with its legal name, about 10,400 of them, no key, no rate card. It
 * is a work of the United States government, so it is public domain, and a
 * company's own name is a fact rather than anyone's creative work. There is no
 * licence to breach and no vendor to pay. It is also the same free SEC source
 * this backend already reads for the ten-year financial statements.
 *
 * Three layers, best first:
 *   1. The curated universe in catalog.ts, which carries hand-written names
 *      for the large caps ("NVIDIA Corp." rather than the SEC's "NVIDIA CORP").
 *   2. The SEC file, for everything else that files with the SEC.
 *   3. A short hand-kept list of popular ETFs. Funds organised as a series of
 *      a trust are not in company_tickers.json at all: SCHD, JEPI and VOO
 *      resolve to nothing there, and the SEC's fund file carries identifiers
 *      without names. These are typed out because there is no free feed that
 *      has them, and a fund's name is a fact like any other.
 *
 * A symbol none of the three knows returns null, and the caller shows the
 * ticker on the ticker line and nothing on the name line. That is the same
 * rule as everywhere else here: we would rather leave a gap than invent.
 */

import { SECTOR_UNIVERSE, symbolProfile } from "@/lib/investing/catalog"

/** A day. The SEC file changes when companies list or rename, not hourly. */
const REVALIDATE = 86400

const SEC_TICKERS = "https://www.sec.gov/files/company_tickers.json"

/**
 * SEC requires a descriptive User-Agent with contact details on every request
 * and answers 403 without one. Same header the statements route sends.
 */
const SEC_HEADERS = { "User-Agent": "FinnaCalc (support@finnacalc.com)" }

/**
 * Funds that file as a series of a trust, so the SEC's ticker file has no row
 * for them. Ordered roughly by how often someone actually holds one.
 */
const FUND_NAMES: Record<string, string> = {
    VOO: "Vanguard S&P 500 ETF",
    VTI: "Vanguard Total Stock Market ETF",
    VT: "Vanguard Total World Stock ETF",
    VXUS: "Vanguard Total International Stock ETF",
    VEA: "Vanguard FTSE Developed Markets ETF",
    VWO: "Vanguard FTSE Emerging Markets ETF",
    VUG: "Vanguard Growth ETF",
    VTV: "Vanguard Value ETF",
    VYM: "Vanguard High Dividend Yield ETF",
    VIG: "Vanguard Dividend Appreciation ETF",
    VNQ: "Vanguard Real Estate ETF",
    BND: "Vanguard Total Bond Market ETF",
    BNDX: "Vanguard Total International Bond ETF",
    VGT: "Vanguard Information Technology ETF",
    VOOG: "Vanguard S&P 500 Growth ETF",
    VB: "Vanguard Small-Cap ETF",
    VO: "Vanguard Mid-Cap ETF",
    SCHD: "Schwab U.S. Dividend Equity ETF",
    SCHG: "Schwab U.S. Large-Cap Growth ETF",
    SCHB: "Schwab U.S. Broad Market ETF",
    SCHF: "Schwab International Equity ETF",
    SCHX: "Schwab U.S. Large-Cap ETF",
    SCHA: "Schwab U.S. Small-Cap ETF",
    SCHP: "Schwab U.S. TIPS ETF",
    JEPI: "JPMorgan Equity Premium Income ETF",
