import { NextRequest, NextResponse } from "next/server";
import { bars, isAlpacaConfigured, type BarAdjustment, type BarTimeframe } from "@/lib/alpaca";

// Price history for the native chart, from Alpaca's bars endpoint.
//
// Response shape (consumed by iOS MarketService.candles):
//   { symbol, range, points: [{ t: epochSeconds, c: close, o, h, l }] }
//
// On 1D the response also carries `session`, the exchange date the bars belong
// to, and `previousClose`, the close before that session opened. Both come out
// of the window already fetched, so neither costs a request. The app needs
// them to say which day it is drawing and to measure the day's move from the
// right reference instead of from the session's first bar.

export const revalidate = 60;

// Range pill → (timeframe, how far back).
//
// How many rows to ask for is NOT a property of the range: it depends on the
// bar size, which the candlestick view overrides per request. See rowsFor.
const RANGES: Record<string, { timeframe: BarTimeframe; days: number }> = {
    "1D": { timeframe: "5Min", days: 4 },
    "1W": { timeframe: "30Min", days: 9 },
    "1M": { timeframe: "1Day", days: 32 },
    "1Y": { timeframe: "1Day", days: 370 },
    // Five years, weekly: the longest window the app offers, and a promise
    // we can keep. The free plan's history runs out around July 2020 for
    // every older listing checked, so a pill reading "all time" would be a
    // lie next to a company that listed in 1980. Five years sits inside that
    // floor with room to spare, and about 260 weekly bars is well under the
    // limit. Whether five years happens to BE a given symbol's whole life is
    // answered per symbol below, since anything that listed recently really
    // is complete.
    "5Y": { timeframe: "1Week", days: 365 * 5 + 7 },
    // Kept so app builds already shipping "ALL" keep working. New callers
    // should ask for 5Y and say five years.
    ALL: { timeframe: "1Week", days: 365 * 20 },
};

// The candlestick view can ask for its own interval.
const INTERVALS: Record<string, BarTimeframe> = {
    "1min": "1Min",
    "5min": "5Min",
    "15min": "15Min",
    "30min": "30Min",
    "1h": "1Hour",
    "1day": "1Day",
    "1week": "1Week",
};

/**
 * Bars a trading day can hold at each size, counting extended hours.
 *
 * Deliberate over-estimates. Asking for more rows than exist costs nothing;
 * asking for fewer silently truncates, and Alpaca truncates from the START of
 * the window, so the bars lost are the newest ones.
 */
const BARS_PER_DAY: Record<BarTimeframe, number> = {
    "1Min": 960,
    "5Min": 192,
    "15Min": 64,
    "30Min": 32,
    "1Hour": 16,
    "1Day": 1,
    "1Week": 0.25,
};

/** Alpaca's largest page. */
const MAX_ROWS = 10_000;

/**
 * How many rows this window needs at this bar size.
 *
 * The limit used to be a property of the range pill, which was right only
 * while every pill used its own default bar size. The candlestick view asks
 * for its own interval, and a month of 30-minute bars against the 1M preset's
 * 40-row limit returned two and a half days of a month-old window: a chart
 * labelled "1M" that had not reached the last four weeks. A week of
 * 5-minute bars stopped two sessions short, and a day of 1-minute bars came
 * back as the previous session, cut off mid-morning.
 *
 * So the rows follow the bars, not the pill.
 */
function rowsFor(timeframe: BarTimeframe, days: number): number {
    const needed = Math.ceil(BARS_PER_DAY[timeframe] * days * 1.1);
    return Math.min(MAX_ROWS, Math.max(100, needed));
}

/**
 * Which exchange day a bar belongs to.
 *
 * Bars are stamped in UTC, and the old code took `t.slice(0, 10)`. That agrees
 * with New York from 00:00 to 19:59 ET and then files the 20:00 ET
 * extended-hours bar under tomorrow, so a late print could invent a session
 * containing exactly one bar.
 */
const exchangeDate = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/New_York",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
}).format;

/**
 * Below this a session is a scatter of dots, not a chart.
 *
 * It was 2, which is the arithmetic minimum for a line and nowhere near
 * enough to be one. The free plan serves the IEX feed, one venue out of many,
 * so a thin name can print two or three bars in a whole pre-market and a
 * stock page opened before the bell drew exactly those: two dots, no line,
 * under today's date. Twelve bars is an hour of a 5-minute session or twelve
 * minutes of a 1-minute one; under that the previous session is drawn
 * instead, labelled with its own date, which is what the app says it is
 * showing anyway.
 */
const MIN_SESSION_BARS = 12;

type Bar = { t: string; c: number; o: number; h: number; l: number };

/**
 * The most recent session that can actually be drawn, plus the close before it.
 *
 * The rule used to be "keep every bar sharing the last bar's date", which
 * breaks in the hour before the open. The free plan serves the IEX feed, one
 * venue out of many, so pre-market prints are sparse: measured on a normal
 * morning, AAPL printed two pre-market bars all day and thinner names printed
 * none. The instant one of those lone bars arrived, the old rule threw away
 * the entire previous session and returned a single point, and a single point
 * draws as an empty card. That is what a user opening the app at 08:50 saw.
 *
 * So: walk back from the newest exchange day and take the first one holding
 * enough bars to plot. A real pre-market session with a handful of prints is
 * kept, extended hours included, which is the "show me pre-market if we have
 * it" half. A day holding one stray print falls through to yesterday, which is
 * the "otherwise show me the last session" half.
 *
 * The chosen date is returned so the app can say which day it is drawing
 * rather than labelling a stale session "today".
 */
function latestDrawableSession(
    series: Bar[]
): { date: string; bars: Bar[]; previousClose: number | null } | null {
    if (series.length === 0) return null;

    const byDate = new Map<string, Bar[]>();
    for (const bar of series) {
        const day = exchangeDate(new Date(bar.t));
        const bucket = byDate.get(day);
        if (bucket) bucket.push(bar);
        else byDate.set(day, [bar]);
    }

    const days = [...byDate.keys()].sort();
    let date = days[days.length - 1];
    for (let i = days.length - 1; i >= 0; i--) {
        if ((byDate.get(days[i]) as Bar[]).length >= MIN_SESSION_BARS) {
            date = days[i];
            break;
        }
    }

    // The last close before the chosen session opened, which is the reference
    // a day's move is measured from. It is already inside the window we
    // fetched, so this costs no extra request. Null when the window does not
    // reach back that far, and null means unknown, never zero.
    const earlier = series.filter((bar) => exchangeDate(new Date(bar.t)) < date);
    const previousClose = earlier.length > 0 ? earlier[earlier.length - 1].c : null;

    return { date, bars: byDate.get(date) as Bar[], previousClose };
}

export async function GET(request: NextRequest) {
    if (!isAlpacaConfigured) {
        return NextResponse.json({ error: "Market data is not configured." }, { status: 503 });
    }

    const params = request.nextUrl.searchParams;
    const symbol = params.get("symbol")?.toUpperCase().trim();
    const range = (params.get("range") ?? "1M").toUpperCase();
    const interval = params.get("interval");

    if (!symbol) {
        return NextResponse.json({ error: "symbol is required" }, { status: 400 });
    }

    // Echo back the range actually SERVED, not the one asked for. An unknown
    // range quietly fell through to the 1M preset while the response still
    // said "6M", so a caller could draw one month of bars under a six-month
    // label and never know.
    const served = RANGES[range] ? range : "1M";
    const preset = RANGES[served];
    const timeframe = interval && INTERVALS[interval] ? INTERVALS[interval] : preset.timeframe;
    const start = new Date(Date.now() - preset.days * 24 * 60 * 60 * 1000);
    const rows = rowsFor(timeframe, preset.days);

    // Total return rather than price return, for callers asking what a
    // holding actually earned. Charts stay on the split-only default.
    const adjustment: BarAdjustment = params.get("adjustment") === "all" ? "all" : "split";

    try {
        const series = await bars(symbol, timeframe, start, rows, revalidate, adjustment);

        // 1D means the latest session, not the last four calendar days: markets
        // close, and a Monday request must not draw Thursday and Friday too.
        // The window above is deliberately wider than a day so a long weekend
        // still returns something; here it's trimmed back to one session.
        const chosen = served === "1D" ? latestDrawableSession(series) : null;
        const trimmed = chosen ? chosen.bars : series;

        const points = trimmed
            .map((bar) => ({
                t: Math.round(Date.parse(bar.t) / 1000),
                c: bar.c,
                o: bar.o,
                h: bar.h,
                l: bar.l,
            }))
            .filter((point) => Number.isFinite(point.t) && Number.isFinite(point.c));

        // On the long window, say whether this is the symbol's whole life or
        // just as far back as the plan reaches.
        //
        // It differs per symbol and the difference is not cosmetic. Every
        // listing older than the free plan's floor comes back starting on the
        // same week (AAPL, KO, GE, XOM and IBM all begin 2020-07-27), so for
        // those "all time" would be a plain lie: Apple listed in 1980.
        // Symbols that listed after the floor really do come back complete,
        // which is why RDDT starts at its 2024 IPO and HOOD at its 2021 one.
        //
        // Decided from the request rather than a hardcoded floor date, so it
        // cannot rot if the plan's horizon moves: a symbol whose first bar
        // sits at the edge of the window we asked for was already trading
        // before it, and one whose first bar is well inside the window began
        // there. The tolerance leans toward reporting "not complete", because
        // over-disclosing costs a sentence and under-disclosing is a false
        // claim about what the user is looking at.
        let coversAllHistory: boolean | undefined;
        let earliest: string | undefined;
        if ((served === "5Y" || served === "ALL") && points.length > 0) {
            const firstBar = points[0].t * 1000;
            const TOLERANCE_MS = 14 * 24 * 60 * 60 * 1000;
            coversAllHistory = firstBar > start.getTime() + TOLERANCE_MS;
            earliest = exchangeDate(new Date(firstBar));
        }

        // `session` and `previousClose` ride along on 1D only. The app needs
        // both to be honest: which day it is actually drawing, and the close
        // the day's move is measured against.
        return NextResponse.json({
            symbol,
            range: served,
            points,
            ...(chosen ? { session: chosen.date, previousClose: chosen.previousClose } : {}),
            ...(coversAllHistory === undefined ? {} : { coversAllHistory, earliest }),
        });
    } catch (err: any) {
        return NextResponse.json({ error: err.message || "Failed to fetch candles." }, { status: 500 });
    }
}

app/api/market-stats/route.ts:
import { NextRequest, NextResponse } from "next/server";
import { asset, isCryptoSymbol } from "@/lib/alpaca";
import { activeSymbolSet, fetchQuotes } from "@/lib/quotes";

// Price + day-change for a set of symbols: the Home tab's "Markets today" row,
// the S&P card, and every holding in a connected portfolio.
//
// Why this exists instead of calling /api/stock per symbol: that route also
// pulls the asset record and a year of bars to render a full stock page, which
// these callers don't show. Here it's quotes only, every symbol in one Alpaca
// snapshot call, cached hard. Fifteen minutes stale is fine for an
// at-a-glance markets row.
//
// THE CAP USED TO BE SIX, AND SILENT.
// -----------------------------------
// This route was written for a markets row of a handful of tickers, and capped
// at six with a bare .slice(). Then the portfolio started asking it to price
// every holding. The app builds that list from a Swift Set, whose iteration
// order changes between launches, so a seven-holding portfolio lost the quote
// for a DIFFERENT holding every time the app started, and the page showed a
// dash beside a real position. From the outside it looked like the data was
// missing; it was thrown away here, after Alpaca had already returned it.
//
// Two lessons are built into what follows. The cap is now high enough for a
// real portfolio, because Alpaca takes every symbol in a single snapshot call
// and the old limit bought us nothing. And when it does bite, the response
// SAYS SO in `truncated` rather than quietly returning a short list that reads
// like "these symbols have no price".

export const revalidate = 900;
export const maxDuration = 30;

// Alpaca's snapshots endpoint takes them all at once, so the only per-symbol
// cost here is the optional name lookup. This is an abuse ceiling, not a
// provider limit: it is far above any real portfolio.
const MAX_SYMBOLS = 120;

export async function GET(request: NextRequest) {
    const { searchParams } = new URL(request.url);
    const asked = (searchParams.get("symbols") ?? "")
        .split(",")
        .map((s) => s.trim().toUpperCase())
        .filter(Boolean);

    // Duplicates would each cost an asset lookup and land on the same key.
    const unique = [...new Set(asked)];
    const symbols = unique.slice(0, MAX_SYMBOLS);
    const truncated = unique.slice(MAX_SYMBOLS);

    if (symbols.length === 0) {
        return NextResponse.json({ error: "symbols is required." }, { status: 400 });
    }

    // Names cost one day-cached asset call each, and the portfolio never shows
    // them: it labels rows with the ticker it already has. `names=0` lets a
    // caller pricing thirty holdings skip thirty requests it has no use for.
    const wantNames = searchParams.get("names") !== "0";

    const [quotes, activeSymbols] = await Promise.all([
        fetchQuotes(symbols, revalidate),
        activeSymbolSet(900),
    ]);

    // A symbol whose day move we cannot state is left out of `stats`
    // entirely, rather than included with changePct: null.
    //
    // Not a style choice, a compatibility one. `stats` is decoded into a Swift
    // array whose changePct was a non-optional Double until this change, and
    // one null anywhere in the array fails the decode for the WHOLE response,
    // not just that row. An app already on someone's phone would lose its
    // markets row and every holding quote the moment a BRK.A turned up. Being
    // absent is the case every version has always handled: the client draws
    // the no-value glyph and says nothing about the day.
    //
    // Once no build older than this is in use, these can come back as rows
    // carrying a price with a null move, which is strictly more information.
    const stats = await Promise.all(
        symbols
            .filter((symbol) =>
                quotes[symbol] && !quotes[symbol].isStale && quotes[symbol].changePct !== null &&
                (isCryptoSymbol(symbol) || !activeSymbols || activeSymbols.has(symbol))
            )
            .map(async (symbol) => {
                const quote = quotes[symbol];
                // Names are day-cached asset lookups, and only equities have one.
                const name =
                    wantNames && !isCryptoSymbol(symbol)
                        ? ((await asset(symbol))?.name ?? null)
                        : null;
                // `change` rides along because the caller cannot reliably
                // recover it: deriving a previous close as
                // price / (1 + changePct / 100) divides by a figure that
                // approaches zero for a stock that nearly halved. The
                // subtraction price - change is exact, and the day chart
                // needs that reference to colour itself against the previous
                // close rather than against its own first bar.
                return { symbol, name, price: quote.price, change: quote.change, changePct: quote.changePct };
            })
    );

    // Unresolved symbols are simply absent, and the client renders a dash for
    // them rather than showing a fabricated figure. Anything cut for being over
    // the ceiling is named separately, because "we did not ask" and "there is no
    // price" are different facts and only one of them is about the market.
    return NextResponse.json(truncated.length ? { stats, truncated } : { stats });
}

app/api/stock/route.ts:
import { NextRequest, NextResponse } from "next/server";
import { asset, bars, isCryptoSymbol } from "@/lib/alpaca";
import { fetchQuote } from "@/lib/quotes";
import { symbolProfile } from "@/lib/investing/catalog";
import { companyName } from "@/lib/investing/names";
import { fundamentalsFor } from "@/lib/investing/fundamentals";
import { symbolAbout } from "@/lib/investing/profiles";

// Everything one symbol's page needs, from Alpaca.
//
// Alpaca is a market-data and brokerage API, not a fundamentals vendor: it
// serves prices, bars, assets and news, and has no company profile, no
// valuation metrics and no analyst data. The fields those used to fill are
// returned as null rather than guessed at, and the iOS sections that read them
// hide themselves on null — see StockStatsFields / StockCompanyFields, whose
// members are all optional for exactly this reason.
//
// The two stats that ARE derivable from price history are: the 52-week high and
// low, summed here from a year of daily bars.
//
// The rest now come from the company's own SEC filings, via lib/investing/
// fundamentals, which reads the same company facts document /api/statements
// already downloads. See that file for what is derivable and what is not: in
// short, a filed figure is a fiscal year old at worst, a market cap is a live
// price against a filed share count, and a multi-class issuer whose share
// count the XBRL API drops gets null rather than a wrong number.

export const revalidate = 60;

async function fiftyTwoWeek(symbol: string): Promise<{ high: number | null; low: number | null }> {
    const start = new Date(Date.now() - 366 * 24 * 60 * 60 * 1000);
    const year = await bars(symbol, "1Day", start, 400, 3600);
    if (year.length === 0) return { high: null, low: null };
    return {
        high: Math.max(...year.map((bar) => bar.h)),
        low: Math.min(...year.map((bar) => bar.l)),
    };
}

export async function GET(request: NextRequest) {
    const symbol = request.nextUrl.searchParams.get("symbol")?.toUpperCase().trim();
    if (!symbol) {
        return NextResponse.json({ error: "Symbol is required." }, { status: 400 });
    }

    try {
        const [quoteSrc, info, window] = await Promise.all([
            fetchQuote(symbol, revalidate),
            isCryptoSymbol(symbol) ? Promise.resolve(null) : asset(symbol),
            fiftyTwoWeek(symbol),
        ]);

        if (!quoteSrc) {
            return NextResponse.json({ error: `No data found for symbol "${symbol}".` }, { status: 404 });
        }

        // After the quote, because a market cap and a P/E are a live price
        // against a filed denominator. Crypto has no filings, and neither do
        // funds; both come back as every-field-null and every row hides.
        const filings = isCryptoSymbol(symbol) || quoteSrc.isStale
            ? null
            : await fundamentalsFor(symbol, quoteSrc.price);

        const quote = {
            "01. symbol": symbol,
            "05. price": String(quoteSrc.price),
            // This block keeps the legacy string shape the app decodes, where
            // "0"/"N/A" already mean "not known" (see MarketCapitalization
            // below). A null move stays on that convention rather than
            // stringifying to the literal "null", which would not parse.
            "09. change": String(quoteSrc.change ?? 0),
            "10. change percent": `${quoteSrc.changePct ?? 0}%`,
        };

        // The hand-kept sector universe knows the company name and sector for
        // the large caps people hold. It is the same list /api/market-overview
        // has always used; this route simply never consulted it, which is why
        // AAPL came back as "AAPL" with a null sector here and as "Apple Inc.",
        // "Technology" one route over.
        const profile = symbolProfile(symbol);
        // Written by us, not filed. The SEC publishes no business description
        // in structured form, so this is a hand-kept list covering the same
        // large caps the sector universe does. See lib/investing/profiles.
        const about = symbolAbout(symbol);
        // companyName layers the curated list over the SEC's free ticker file,
        // so this covers roughly 10,400 issuers rather than the 105 the
        // curated universe carries. Falling back to the symbol is last, and
        // it is why every page used to be titled with its own ticker.
        const name = (await companyName(symbol)) || info?.name || quoteSrc.name || symbol;
        const overview = {
            Name: name,
            // "0" and "N/A" are what the app already reads as "not known", so
            // an issuer whose filings don't support a figure keeps the old
            // value and the row keeps hiding itself.
            MarketCapitalization: filings?.marketCap != null ? String(Math.round(filings.marketCap)) : "0",
            // The app treats this exact string as "nothing to show", so a
            // symbol outside the curated list keeps hiding its paragraph.
            Description: about?.description ?? "No description available.",
            Logo: "",
            // Sent pre-formatted because the app prints this one verbatim.
            PERatio: filings?.peRatio != null ? filings.peRatio.toFixed(2) : "N/A",
        };

        const stats = {
            high52: window.high,
            low52: window.low,
            // Beta is a regression of this symbol's returns against an index.
            // Nothing in a filing carries it and Alpaca doesn't publish one,
            // so it stays null until something computes it from bars.
            beta: null,
            epsTTM: filings?.epsTTM ?? null,
            dividendYield: filings?.dividendYield ?? null,
            netMargin: filings?.netMargin ?? null,
            revenueGrowth: filings?.revenueGrowth ?? null,
            grossMargin: filings?.grossMargin ?? null,
            // MILLIONS of shares. The app's formatter divides by 1000 again
            // above 1000 to print "B", which is the Finnhub convention this
            // field was written against and which the iOS side still expects.
            sharesOutstanding:
                filings?.sharesOutstanding != null ? filings.sharesOutstanding / 1_000_000 : null,
        };

        const company = {
            exchange: info?.exchange ?? null,
            industry: null,
            sector: profile?.sector ?? null,
            ceo: null,
            // Not in SEC structured data. `dei` carries two facts per filer,
            // the cover-page share count and the public float; a headcount
            // lives in the 10-K's prose. Typing one by hand would print a
            // real, checkable figure that goes stale every February.
            employees: null,
            ipo: null,
            website: null,
            country: null,
            headquarters: about?.headquarters ?? null,
        };

        // Retired-ticker resolution came from a vendor feed that has been
        // removed with the rest of them; the field stays so older app builds
        // keep decoding this payload.
        return NextResponse.json({
            quote,
            overview,
            stats,
            company,
            alias: null,
            marketData: {
                asOf: quoteSrc.asOf,
                isStale: quoteSrc.isStale,
                assetStatus: info?.status ?? null,
            },
        });
    } catch (err: any) {
        return NextResponse.json({ error: err.message || "Failed to fetch stock data." }, { status: 500 });
    }
}

app/api/dividends/route.ts:
import { NextRequest, NextResponse } from "next/server";
import { cashDividends, isAlpacaConfigured } from "@/lib/alpaca";

/**
 * Dividends actually paid, and dividends already declared, for a set of
 * holdings.
 *
 * WHY THIS ROUTE EXISTS AT ALL
 * ----------------------------
 * The Dividends card in Portfolio Analysis has never had data. Its only input
 * was a yield percentage that /api/stock hardcodes to null, so the card told
 * an investor holding SCHD, KO and JEPI that none of their holdings pays a
 * dividend, and its "upcoming" list was one row per paying holding with the
 * literal words "About every 3 months" and an annual figure divided by four.
 * There were no dates anywhere in the product.
 *
 * WHY ALPACA AND NOT THE SEC
 * --------------------------
 * The SEC's XBRL data does carry dividend amounts, and plenty of them: KO has
 * 94 quarters of CommonStockDividendsPerShareDeclared. But every point is
 * stamped with a FISCAL PERIOD, not a payment date. It can tell you a company
 * paid $0.39 during the quarter ending 2018-09-28; it cannot tell you the day
 * it went ex, or the day the cash arrived. A calendar needs dates, so SEC data
 * can total a year and cannot place a single dot.
 *
 * Alpaca's corporate actions carry ex_date, record_date and payable_date
 * alongside the rate, and a window whose end is in the future returns
 * dividends that have been declared but not yet paid. That is both halves the
 * card wants, from credentials this backend already holds.
 *
 * WHAT IT STILL CANNOT DO, so the app does not pretend otherwise:
 *  • Nothing is forecast. A dividend appears here only once the company has
 *    declared it. "Four more like the last one" is a guess about a decision a
 *    board has not made, and it is not made here.
 *  • The amount is per share as of the ex date. Multiplying by today's share
 *    count is the app's business, and it is only right for shares held on that
 *    date, which is why the client labels a past payment as an estimate unless
 *    the holding predates it.
 *  • Coverage is whatever Alpaca knows. A symbol with no rows is absent, and
 *    absent means unknown, never "pays nothing".
 */

export const revalidate = 21600;
export const maxDuration = 30;

/** Far more than a real portfolio, and an abuse ceiling rather than a limit. */
const MAX_SYMBOLS = 60;

/** How far back the paid history reaches. */
const LOOKBACK_DAYS = 400;

/**
 * How far forward to ask for declared dividends. A quarter plus a margin: a
 * board typically declares four to eight weeks before the ex date, so a wider
 * window returns nothing extra and a narrower one clips the next payment.
 */
const LOOKAHEAD_DAYS = 120;

export async function GET(request: NextRequest) {
    if (!isAlpacaConfigured) {
        return NextResponse.json({ error: "Market data is not configured." }, { status: 503 });
    }

    const asked = (request.nextUrl.searchParams.get("symbols") ?? "")
        .split(",")
        .map((s) => s.trim().toUpperCase())
        .filter(Boolean);

    const unique = [...new Set(asked)];
    const symbols = unique.slice(0, MAX_SYMBOLS);
    const truncated = unique.slice(MAX_SYMBOLS);

    if (symbols.length === 0) {
        return NextResponse.json({ error: "symbols is required." }, { status: 400 });
    }

    const now = Date.now();
    const start = new Date(now - LOOKBACK_DAYS * 86400_000);
    const end = new Date(now + LOOKAHEAD_DAYS * 86400_000);

    try {
        const rows = await cashDividends(symbols, start, end, revalidate);

        const today = new Date().toISOString().slice(0, 10);
        const payments = rows
            .map((row) => {
                // Ex date is the one a dividend is really keyed on, and the one
                // Alpaca always sends. Payable is what a user cares about and
                // is occasionally absent, so it stays nullable rather than
                // being backfilled with the ex date, which would be a date we
                // invented.
                const exDate = row.ex_date ?? null;
                const payDate = row.payable_date ?? null;
                const anchor = payDate ?? exDate;
                if (!anchor || !Number.isFinite(row.rate)) return null;
                return {
                    symbol: row.symbol?.toUpperCase() ?? "",
                    /** Per share, in the listing currency. */
                    rate: row.rate,
                    exDate,
                    payDate,
                    recordDate: row.record_date ?? null,
                    /** Whether the cash has already been paid out. */
                    paid: anchor <= today,
                    special: row.special === true,
                };
            })
            .filter((row): row is NonNullable<typeof row> => row !== null && row.symbol !== "")
            .sort((a, b) => (a.payDate ?? a.exDate ?? "").localeCompare(b.payDate ?? b.exDate ?? ""));

        // Symbols that returned nothing are named, because "Alpaca has no
        // dividend record for this" and "this pays no dividend" are different
        // facts and the card must not print the second one.
        const covered = new Set(payments.map((p) => p.symbol));
        const noRecord = symbols.filter((s) => !covered.has(s));

        return NextResponse.json({
            payments,
            noRecord,
            windowStart: start.toISOString().slice(0, 10),
            windowEnd: end.toISOString().slice(0, 10),
            source: "Alpaca corporate actions",
            ...(truncated.length ? { truncated } : {}),
        });
    } catch (err: any) {
        return NextResponse.json({ error: err.message || "Failed to fetch dividends." }, { status: 500 });
    }
}
